function lastChapterTitle(media,bookid) {

    let url;
    let last;
    if (media == "番茄") {
    	    last=fq_last(bookid);
        return last
    } else if (media == "七猫") {
    	   last=qm_last(bookid);
        return last

    } else {
    	return '无'
    	}
}


function fq_last(bookid) {
	let url = `https://api5-normal-sinfonlineb.fqnovel.com/reading/bookapi/multi-detail/v/?aid=1967&iid=1&version_code=999&book_id=${bookid}`;
        let last =JSON.parse(java.ajax(url)).data[0]; 
        return last["last_chapter_title"]+" · "+java.timeFormat(last["last_chapter_update_time"]*1000);

	}

function qm_last(bookid) {
